import json
from pathlib import Path
p=Path(__file__).parent/'chunks/0004.json';d=json.loads(p.read_text())
translations={
 't000038': '''Rezistența față de Partid ia diverse forme de-a lungul romanului. Hotărârea lui Winston de a ține un jurnal este un act de rebeliune, o încercare de a-și păstra gândurile și amintirile în fața revizuirii neîncetate a istoriei de către Partid. Explorarea trecutului prin obiecte precum prespapierul de sticlă și prin discuții cu proli mai în vârstă este o cale de a rezista controlului Partidului asupra istoriei și memoriei.''',
 't000039': '''Forma de rezistență a Juliei este mai pragmatică și mai personală. Ea se revoltă nu dintr-o ideologie politică, ci din dorința de a se bucura de plăcerile vieții. Capacitatea ei de a se descurca în sistem încălcându-i pe ascuns regulile reprezintă un alt fel de sfidare, concentrată pe satisfacția imediată mai degrabă decât pe schimbarea pe termen lung.''',
 't000040': '''Consecințele rezistenței sunt aspre, după cum descoperă Winston și Julia. Capturarea, torturarea și, în cele din urmă, convertirea lor arată eficiența nemiloasă cu care Partidul zdrobește opoziția. Distrugerea relației lor prin tortură reprezintă victoria finală a Partidului asupra legăturilor umane individuale.''',
 't000041': '''Totuși, chiar în fața unui control atât de cuprinzător, romanul sugerează că puterea spiritului uman de a rezista nu poate fi stinsă pe deplin. Însăși existența relației dintre Winston și Julia, oricât de scurtă, mărturisește forța durabilă a legăturii umane și dorința înnăscută de libertate.''',
 't000042': 'Capitolul al patrulea: Puterea, adevărul și natura umană',
 't000043': '''În lumea distopică din „1984”, George Orwell cercetează în profunzime natura puterii, maleabilitatea adevărului și esența naturii umane. Acest capitol explorează temele interconectate și scoate în evidență observațiile lui Orwell despre condiția umană sub conducerea totalitară.''',
 't000044': '''Atitudinea Partidului față de putere în Oceania este absolută și atotcuprinzătoare. După cum îi explică O’Brien lui Winston în timpul interogatoriului, pentru Partid puterea nu este un mijloc către un scop, ci un scop în sine. Țelul nu este bunăstarea oamenilor sau crearea unei societăți mai bune, ci doar păstrarea și sporirea propriei puteri la nesfârșit.''',
 't000045': '''Această urmărire a puterii de dragul puterii duce la o societate clădită pe frică, manipulare și control. Partidul nu caută doar ascultare, ci predarea completă a voinței și identității individuale. După cum spune O’Brien: „Nu ne mulțumim cu o ascultare lipsită de inițiativă și nici cu cea mai umilă supunere. Când, în cele din urmă, te predai nouă, trebuie să o faci de bunăvoie.”''',
 't000046': '''În Oceania, adevărul este fluid și supus capriciilor Partidului. Ministerul Adevărului, unde lucrează Winston, rescrie permanent istoria pentru a o potrivi relatării curente a Partidului. Manipularea depășește faptele istorice și cuprinde evenimentele prezente, ba chiar realitatea elementară. Lozinca Partidului, „Cine controlează prezentul controlează trecutul. Cine controlează trecutul controlează viitorul”, concentrează această abordare a adevărului.''',
 't000047': '''Maleabilitatea adevărului este întărită de conceptul de dublugândit, capacitatea de a susține simultan două convingeri contradictorii. Membrii Partidului trebuie să accepte drept adevăr orice declară acesta, chiar dacă se contrazice cu fapte stabilite anterior sau cu propriile amintiri. Erodarea adevărului obiectiv dezorientează populația și face rezistența aproape imposibilă.''',
 't000048': '''Explorarea naturii umane în roman este deosebit de emoționantă în descrierea drumului lui Winston. La început, el crede în rezistența spiritului uman și în puterea convingerii individuale. Se agață de ideea că există ceva înnăscut uman pe care Partidul nu îl poate modifica sau distruge.''',
 't000049': '''Experiențele lui Winston în Ministerul Iubirii pun însă această credință la încercare. „Reabilitarea” lui nu înseamnă doar tortură fizică, ci și destrămarea sistematică a personalității și convingerilor sale. O’Brien nu urmărește doar să-l facă pe Winston să se supună, ci să-i schimbe fundamental felul de a gândi și de a percepe realitatea.''',
 't000050': '''Punctul culminant al procesului are loc în Camera 101, unde Winston își înfruntă cea mai mare teamă. Această confruntare îl face să-și trădeze valorile și sentimentele cele mai profunde, inclusiv iubirea pentru Julia. Frângerea lui Winston arată că Partidul poate pătrunde până în miezul naturii umane și o poate remodela după voia sa.''',
}
assert set(translations)=={x['id'] for x in d['segments']}
for seg in d['segments']:seg['translation']=translations[seg['id']]
p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('translated',len(d['segments']))
